pub fn is_palindrome(s: &str) -> bool {
    let mut left: usize = 0;
    let mut right: usize = s.chars().count() as usize - 1;
    while left < right {
        let c = s.chars().nth(left).unwrap();
        if !is_letter_or_digit(c) {
            left += 1;
            continue;
        }
        let d = s.chars().nth(right).unwrap();
        if !is_letter_or_digit(d) {
            right -= 1;
            continue;
        }
        if c != d {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}

fn is_letter_or_digit(c: char) -> bool {
    c.is_alphabetic() || c.is_digit(10)
}

