pub fn find(v: &[i32], target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = v.len() - 1;
    while left <= right {
        let mid = left + (right - left) / 2;
        let value = &v[mid];
        if *value == target {
            return Some(mid);
        } else if *value < target {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    None
}

