pub fn median(v: &[f64]) -> Option<f64> {
    let mut left = v;
    let mut right = v;
    let mut count = 0;
    while let Some(x) = left.pop() {
        right.push(x);
        count += 1;
    }
    if count == 0 {
        return None;
    }
    let mid = count / 2;
    let (lo, hi) = if count % 2 == 0 {
        let (x, y) = left.split_at(mid);
        (x, y) as (f64, f64)
    } else {
        let (x, y) = left.split_at(mid + 1);
        (x, y) as (f64, f64)
    };
    if lo < hi {
        Some((lo + hi) / 2.0)
    } else {
        None
    }
}

