pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    let mut r = 0u8;
    let mut g = 0u8;
    let mut b = 0u8;
    if s.chars().next().map_or(false, |c| c == '#') {
        for (i, c) in s.chars().enumerate() {
            let digit = match c {
                '0'..='9' => 0u8 + c.to_digit(16).unwrap(),
                'a'..='f' => 10u8 + c.to_digit(16).unwrap(),
                'b'..='f' => 11u8 + c.to_digit(16).unwrap(),
                'c'..='f' => 12u8 + c.to_digit(16).unwrap(),
                'd'..='f' => 13u8 + c.to_digit(16).unwrap(),
                _ => return None,
            };
            if i > 0 {
                b = (b << 4) + digit;
            } else {
                r = digit;
            }
        }
    } else {
        return None;
    }
    Some((r, g, b))
}

