pub fn second_largest(v: &[i32]) -> Option<i32> {
    let mut left = v.iter().copied();
    let mut right = left.next().copied();
    let mut largest = left.next().copied();
    if let Some(x) = largest {
        left = left.filter(|x| x != x);
    }
    while let Some(x) = right.next().copied() {
        if x != largest {
            left = left.filter(|x| x != x);
            right = left.chain(std::iter::once(x));
        }
    }
    if let Some(x) = left.next() {
        Some(x)
    } else {
        None
    }
}

