    if k == 0 || k >= v.len() {
        return v.to_vec();
    }
    let length = v.len();
    let mut out = v.to_vec();
    let shift = k % length;
    out[0..length - shift].copy_from_slice(&out[shift..]);
    out[length - shift..].copy_from_slice(&out[0..length - shift]);
    out
}

